import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"6、【訟】 坎下乾上","description":"周易尚氏學 - 6、【訟】 坎下乾上","frontmatter":{"title":"6、【訟】 坎下乾上","description":"周易尚氏學 - 6、【訟】 坎下乾上"},"headers":[],"relativePath":"classics/shangshi/011.md","filePath":"classics/shangshi/011.md"}'),s={name:"classics/shangshi/011.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_6、【訟】-坎下乾上" tabindex="-1">6、【訟】 坎下乾上 <a class="header-anchor" href="#_6、【訟】-坎下乾上" aria-label="Permalink to “6、【訟】 坎下乾上”">​</a></h1><p>乾陽上升。坎水下降。乃乾即在上。坎即在下。違行。氣不交。故曰訟。二陽居陰中。故有孚。坎中實。故窒。坎憂故惕。二雖不當位。居中。故吉。二無應。遇敵。故終兇。九五中正。故利見大人。坤為大川。二入之不當位。無應與。不能出。(若解則能出)沈淪於坤水之中。故曰不利涉大川。</p><p>彖曰。訟上剛下險。險而健訟。訟有孚窒惕。中吉。剛來而得中也。終兇。訟不可成也。利見大人。尚中正也。不利涉大川。入於淵也。</p><p>剛來得中謂二也。中正謂五也。坤為淵。易林震之復雲。藏匿淵底。言復陽居坤下。故曰藏匿淵底。是以坤為淵也。今二入居坤中。故曰入於淵。而上無應不能出。沈溺淵中。故曰不利。</p><p>象曰。天與水違行。訟。君子以作事謀始。</p><p>需水上乾下。故氣交。反之則背道而馳。愈去愈遠。故曰違行。行道也。違行言異道而行也。坎為謀。坤為事。二居坤中。故曰作事。二無應。故入不能出。若慎始則免矣。卦氣以下為始。王弼雲。凡訟之起。契之不明。孔疏由於初時契要之過。慎始制契。則訟端絕。按乾坎皆為信。契要者信也。王注優於各家。</p><p>初六。不永所事。小有言。終吉。</p><p>事。訟事也。訟始於初。然初有應。初四相上下成中孚。各當位。則訟事息矣。故曰不永所事。坎上下兌口相背。故有言。有言即訟也。不永故曰小有言。有應故終吉。</p><h3 id="象曰。不永所事。訟不可長也。雖小有言。其辯明也。" tabindex="-1">象曰。不永所事。訟不可長也。雖小有言。其辯明也。 <a class="header-anchor" href="#象曰。不永所事。訟不可長也。雖小有言。其辯明也。" aria-label="Permalink to “象曰。不永所事。訟不可長也。雖小有言。其辯明也。”">​</a></h3><p>兌口多。故曰辯明。</p><p>九二。不克訟。歸而逋。其邑人三百戶。無眚。</p><p>坎為隱伏。故曰逋。上無應。故不克訟。不克訟故逋。逋逃也。逃歸何處乎。二居坤中。坤為邑為百為戶。茹敦和曰。坎數三。故曰其邑人三百戶。言二選於坤邑之中也。坎為眚。二逋坤中。孚於上下。故無眚。眚。釋文馬雲災也。</p><h3 id="象曰。不克訟。歸逋竄也。自下訟上。患至掇也。" tabindex="-1">象曰。不克訟。歸逋竄也。自下訟上。患至掇也。 <a class="header-anchor" href="#象曰。不克訟。歸逋竄也。自下訟上。患至掇也。" aria-label="Permalink to “象曰。不克訟。歸逋竄也。自下訟上。患至掇也。”">​</a></h3><p>上謂五。五剛。二與為敵。故曰自下訟上。吳先生曰。掇。借為輟。止也。愚按集韻掇音輟讀若朵。逸周書曰。綿綿不絕。蔓蔓若何。毫末不掇。將成斧柯。不掇即不輟。言毫末雖微。長而不止。即成斧柯。然則掇輟古通用。又河北方言謂人避事曰掇避。正與此同。掇或作躲。玉篇身也。無避匿之義。非也。歸而逋。即輟訟矣。輟之故因不克訟而有患也。釋文鄭作惙。憂也。近師俞樾又作綴。言禍患之來。聯綴不已也。但小象原以釋經文。作惙作綴於逋義皆無涉。若作輟。則正釋逋義也。逋而輟訟。訟止故無眚。</p><p>六三。食舊德。貞厲。終吉。或從王事。無成。</p><p>乾為舊為德。坎為食。三承重陽。故曰食舊德。失位故貞厲。承陽有應故終吉。三承乾。乾為王。故曰從王事。坤柔故無成。義詳坤六三前釋。</p><h3 id="象曰。食舊德。從上吉也。" tabindex="-1">象曰。食舊德。從上吉也。 <a class="header-anchor" href="#象曰。食舊德。從上吉也。" aria-label="Permalink to “象曰。食舊德。從上吉也。”">​</a></h3><p>從上即承乾。</p><p>九四。不克訟。復即命。渝。安貞。吉。</p><p>陽遇陽則窒。故不克訟。巽為命。即。就也。安也。初有應。言復初而安命也。渝變也。訟則爭。爭則不安。不訟則變而為安貞矣。故吉也。</p><h3 id="象曰。復即命。渝安貞吉。不失也。" tabindex="-1">象曰。復即命。渝安貞吉。不失也。 <a class="header-anchor" href="#象曰。復即命。渝安貞吉。不失也。" aria-label="Permalink to “象曰。復即命。渝安貞吉。不失也。”">​</a></h3><p>失與軼通。荀子哀公篇。其馬將失。即其馬將軼也。軼突也。過也。左傳隱九年。懼其侵軼我也。說文車相出也。即從後出前也。不軼即不前出也。釋安貞之義也。與隨初。比二。小畜初。同。</p><p>九五。訟元吉。</p><p>五位極尊。故曰元。五中正。故訟吉。</p><h3 id="象曰。訟元吉。以中正也。" tabindex="-1">象曰。訟元吉。以中正也。 <a class="header-anchor" href="#象曰。訟元吉。以中正也。" aria-label="Permalink to “象曰。訟元吉。以中正也。”">​</a></h3><p>有中而不正者。有正而不中者。中且正。無不吉。</p><p>上九。或錫之韖帶。終朝三褫之。</p><p>說文韖大帶也。錫命也。上應三。三巽為帶。乾大故曰韖帶。乃巽為隕落。故終朝三褫之。褫奪也。坤為夜。乾為朝。上居乾終。故曰終朝。與乾三終日同義。上應三。三體離。離卦數三。(此數失傳。祇易林洞林邵子用之)故曰三褫。先儒不知巽為隕落。(象本左氏。後祇易林用之)褫之故。全在巽。故無得解者。豈知中孚初九雲。有它不燕。以應四巽也。姤九四。包無魚。鼎九四。鼎折足。大過九四。有它吝。皆以應初巽也。例甚明也。釋文褫鄭本作扦。惠氏棟據淮南人間訓。盜扦其衣被。高誘注云。扦奪也。是仍與褫同。乃宋項安世周易玩辭。引鄭注曰。三扦。三加之也。後楊慎臧琳朱芹等。頗祖述其說。謂三扦其紳。以為誇耀。故象曰不足敬。但論語之拖紳。因孔子病臥。君來視。故加紳於朝服。以為敬。今非病臥。曰束紳垂紳皆可。曰拖紳。似不合也。</p><h3 id="象曰。以訟受服。亦不足敬也。" tabindex="-1">象曰。以訟受服。亦不足敬也。 <a class="header-anchor" href="#象曰。以訟受服。亦不足敬也。" aria-label="Permalink to “象曰。以訟受服。亦不足敬也。”">​</a></h3><p>乾為敬。旋得旋失。故不足敬。</p>',30)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
